import type { Header } from '@tonejs/midi/dist/Header';
import { parseMidi } from 'midi-file';

import { makeExpression } from 'app/services/MelodiesService/expression';
import type { NoteTechnique } from 'app/services/MelodiesService/types';

export type PitchEvent = { tick: number; cents: number };

export const combinePitchEvents = (a: PitchEvent[], b: PitchEvent[]) => {
  if (!b.length) return a;
  if (!a.length) return b;
  let first = 0,
    second = 0;
  return [
    ...a.map(point => ({ ...point, source: 0 })),
    ...b.map(point => ({ ...point, source: 1 })),
  ]
    .sort((x, y) => x.tick - y.tick)
    .map(point => {
      if (point.source === 0) first = point.cents;
      else second = point.cents;
      return { tick: point.tick, cents: first + second };
    });
};

export const expressionFromEvents = (
  events: PitchEvent[],
  start: number,
  end: number,
  header: Header,
  techniques?: NoteTechnique[],
  includeGestureEnd = false,
) => {
  // Events at end belong to the next note. A held value before start does
  // belong to this one, including notes shorter than one MIDI tick.
  let low = 0,
    high = events.length;
  while (low < high) {
    const middle = (low + high) >>> 1;
    if (events[middle].tick <= start) low = middle + 1;
    else high = middle;
  }
  const selected: PitchEvent[] = [
    { tick: start, cents: events[low - 1]?.cents ?? 0 },
  ];
  for (let i = low; i < events.length && events[i].tick <= end; i++) {
    if (events[i].tick === end) {
      // alphaTab's first terminal point completes the preceding gesture;
      // later points at this tick may reset the next attack of the same key.
      if (includeGestureEnd) selected.push(events[i]);
      break;
    }
    selected.push(events[i]);
  }
  const begin = header.ticksToSeconds(start);
  const duration = header.ticksToSeconds(end) - begin;
  return makeExpression(
    selected.map(event => ({
      position: (header.ticksToSeconds(event.tick) - begin) / duration,
      cents: event.cents,
    })),
    techniques,
  );
};

/** Read channel state before @tonejs/midi splits tracks by program/channel.
 * RPN 0 is semitones + cents; each channel has independent wheel/range state. */
export const readMidiPitchAutomation = (data: Uint8Array) => {
  const events = parseMidi(data)
    .tracks.flatMap((track, trackIndex) => {
      let tick = 0;
      return track.flatMap((event, order) => {
        tick += event.deltaTime;
        return event.type === 'pitchBend' || event.type === 'controller'
          ? [{ event, tick, trackIndex, order }]
          : [];
      });
    })
    .sort(
      (a, b) =>
        a.tick - b.tick || a.trackIndex - b.trackIndex || a.order - b.order,
    );
  const channels = Array.from({ length: 16 }, () => ({
    msb: 127,
    lsb: 127,
    semitones: 2,
    cents: 0,
    wheel: 0,
    points: [] as PitchEvent[],
  }));
  events.forEach(({ event, tick }) => {
    const state = channels[event.channel];
    let changed = false;
    if (event.type === 'pitchBend') {
      state.wheel = event.value / 8192;
      changed = true;
    } else {
      const { controllerType: cc, value } = event;
      if (cc === 101) state.msb = value;
      if (cc === 100) state.lsb = value;
      if (state.msb === 0 && state.lsb === 0) {
        if (cc === 6) {
          state.semitones = value;
          changed = true;
        }
        if (cc === 38) {
          state.cents = value;
          changed = true;
        }
      }
      if (cc === 121) {
        state.wheel = 0;
        state.msb = state.lsb = 127;
        changed = true;
      }
    }
    if (changed)
      state.points.push({
        tick,
        cents: state.wheel * (state.semitones * 100 + state.cents),
      });
  });
  return channels.map(state => state.points);
};
