export type Scale = keyof typeof scales;
export type Mode =
  | 'custom'
  | typeof scales['elevenTone']['modes'][number]
  | typeof scales['chromatic']['modes'][number]
  | typeof scales['diatonic']['modes'][number]
  | typeof scales['pentatonic']['modes'][number]
  | typeof scales['blues']['modes'][number]
  | typeof scales['jazz']['modes'][number]
  | typeof scales['harmonic']['modes'][number];

const getMode = (notes: JustNote[], shift: number): JustNote[] => {
  if (shift % 12 === 0) {
    return notes;
  }
  const shiftedScale = [
    ...notes.slice(shift, notes.length),
    ...notes.slice(0, shift),
  ];
  const interval = scales.chromatic.intervals.findIndex(
    note => note === shiftedScale[0],
  );
  return shiftedScale.map(
    // TODO pitch JustNote, not Note
    note => splitNote(pitchNote(`${note}4`, -interval))[0],
  );
};

export const getScale = (
  scaleName: Scale,
  mode: Mode,
  customScale?: JustNote[],
): JustNote[] => {
  if (scaleName === 'custom')
    return customScale?.length ? customScale : chromaticNotes;
  const basicScale = scales[scaleName];
  const modeIndex = basicScale.modes.findIndex(m => m === mode);
  if (modeIndex === -1) {
    console.warn(`No mode "${mode}" for "${scaleName}" scale`);
    return basicScale.intervals;
  }
  return getMode(basicScale.intervals, modeIndex);
};
